css:
.loader { position: relative; width: var(--loader-size); height: calc(var(--loader-size) * .55); border-radius: 9999px; background: color-mix(in srgb, var(--loader-color) 25%, transparent); animation: twTrack calc(var(--loader-speed) * 2) ease-in-out infinite; }
.loader .knob { position: absolute; top: 10%; left: 3%; width: calc(var(--loader-size) * .45); height: 80%; border-radius: 9999px; background: var(--loader-color); animation: twKnob calc(var(--loader-speed) * 2) cubic-bezier(.4, 0, .2, 1) infinite; }
@keyframes twKnob { 0%, 10% { left: 3%; } 45%, 55% { left: 52%; } 90%, 100% { left: 3%; } }
@keyframes twTrack { 0%, 10%, 90%, 100% { filter: saturate(.4); } 45%, 55% { filter: saturate(1.5); } }
